#!/usr/bin/env python3
"""Publish honest source and actual-renderer Dreamland profile comparison."""
import argparse,json,shutil
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[2]
p=argparse.ArgumentParser();p.add_argument('--out',type=Path,default=Path('/tmp/dreamland-presentation'));args=p.parse_args();out=args.out;out.mkdir(parents=True,exist_ok=True)
for name,source in [('reference.png','/tmp/ra-third/reference.png'),('source-contact.png','/tmp/dreamland-objects-contact.png'),('composition-restored.png','/tmp/dreamland-match/restored.png'),('composition-unrestored.png','/tmp/dreamland-match/unrestored.png'),('composition-audit.json','/tmp/dreamland-match/audit.json'),('objects-manifest.json',ROOT/'assets/ArtTrials/DreamlandObjects/manifest.json'),('terrain-manifest.json',ROOT/'assets/ArtTrials/DreamlandTerrain/manifest.json')]:
 shutil.copyfile(source,out/name)
geo=[]
for name,label in [('athalmer-dreamland-unrestored','Athalmer, unrestored'),('athalmer-dreamland-restored','Athalmer, restored'),('athalmer-dreamland-tile-boundary','Across the map tile boundary')]:
 source=Path('/tmp/dreamland-final')/(name+'.png')
 if source.exists():
  shutil.copyfile(source,out/(name+'-full.png'));Image.open(source).crop((0,96,352,448)).save(out/(name+'.png'))
  report=source.with_suffix('.json');shutil.copyfile(report,out/report.name)
  geo.append(f'<figure><a href="{name}-full.png"><img src="{name}.png" alt="{label}"></a><figcaption>{label} · <a href="{name}.json">audit</a></figcaption></figure>')
for name,label in [('forest','Mapped woodland — DeepForest positions'),('shoreline','Shoreline — water and lamps')]:
 source=Path('/tmp/dreamland-complete')/(name+'-dreamland-unrestored.png')
 if source.exists():
  Image.open(source).crop((0,96,352,448)).save(out/(name+'.png'))
  geo.append(f'<figure><img src="{name}.png" alt="{label}"><figcaption>{label}. Earlier size review; latest 2× source scale shown above.</figcaption></figure>')
(out/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dreamland reference profile</title><style>*{box-sizing:border-box}body{margin:0;background:#171d21;color:#edf1df;font:16px/1.5 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:24px}h1{font-size:32px}h2{margin-top:44px}a{color:#bfe57f}p{max-width:1000px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,350px),1fr));gap:18px}.geo{grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr))}figure{margin:0;background:#252d31;padding:12px;border-radius:8px}img{width:100%;height:auto;display:block;image-rendering:pixelated}figcaption{margin-top:10px;color:#cbd3bf}.pill{display:inline-block;border:1px solid #7c9363;padding:10px 16px;border-radius:8px}.wide{max-width:1100px}code{color:#d6e9b7}</style><main><h1>Dreamland: reference tiles on the game renderer</h1><p>The installed Fantasy Dreamland Reborn source now supplies olive grass patchwork, native pale paving, red-roof houses, round trees, wooden hanging lanterns, fountains, crates and signs. This is renderer artwork, not image-generated concept art.</p><p><a class="pill" href="http://localhost:8000/index.html?artTrial=dreamland&deepforest=on">Open the geographic game with Dreamland</a></p><h2>Reference and renderer composition</h2><p>The authored composition below exercises the production object and terrain hooks. Camera layout is approximate; terrain is generated from a fixture grid. Its stone strip is civic ground, while the geographic views below exercise real vector roads and their varied paving. Lighting and interface overlays are hidden here to compare the source palette. They remain normal in the real game.</p><div class="grid"><figure><img src="reference.png" alt="Original supplied Dreamland village reference"><figcaption>Supplied reference.</figcaption></figure><figure><img src="composition-restored.png" alt="Restored authored composition using production Dreamland hooks"><figcaption>Restored composition, actual renderer. <a href="composition-audit.json">Object and texture audit</a>.</figcaption></figure><figure><img src="composition-unrestored.png" alt="Same authored objects before restoration"><figcaption>Same objects before restoration: lamps unlit, houses remain identifiable wrecks.</figcaption></figure></div><h2>Real Kelowna geometry</h2><p>These use the normal geographic tile loader and generation pipeline. Object IDs, coordinates, logical landcover and lamp positions are unchanged. The restored screenshot uses an isolated review save and the existing restoration APIs. Runtime lighting accounts for the darker palette away from the player.</p><div class="grid geo">'''+''.join(geo)+'''</div><h2>Native source pieces</h2><p><a href="objects-manifest.json">Object crop/assembly manifest</a> · <a href="terrain-manifest.json">Terrain source manifest</a>. Native source pixels, without synthesized props. Houses fit actual footprints; tree growth still selects smaller or mature art. Lamp glass and light emitters share measured offsets.</p><figure class="wide"><img src="source-contact.png" alt="Reviewed native house tree lamp fountain ground and prop crops"><figcaption>Reviewed source assets. Well, stacked crates and sparse ground-speck candidates are included for provenance, but not newly spawned by the profile.</figcaption></figure><h2>Deliberate differences</h2><p>World geometry determines placement. No cliffs, fences, benches, large grass clumps or extra interactables are added. Wrecks retain existing ruin artwork because the reviewed source provides no equivalent ruin set. Temples, castles, wizard/turret structures, fruit-tree harvest states, dead-tree variants and characters retain their gameplay-specific art. Entering Home keeps the real open interior. The profile does not replace the map with the promotional town layout.</p></main></html>''')
print(out)
